import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"Connect a model","description":"Configure the chat model, four protocols, and the Codex executor.","frontmatter":{"title":"Connect a model","description":"Configure the chat model, four protocols, and the Codex executor.","outline":[2,3]},"headers":[],"relativePath":"en/guide/models.md","filePath":"en/guide/models.md","lastUpdated":null}'),r={name:"en/guide/models.md"};function n(s,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="connect-a-model" tabindex="-1">Connect a model <a class="header-anchor" href="#connect-a-model" aria-label="Permalink to &quot;Connect a model&quot;">​</a></h1><p class="lead">Hearth configures the chat model and the Codex executor separately. The chat model drives the native agent runtime; the Codex executor handles code and repository work.</p><h2 id="chat-model" tabindex="-1">Chat model <a class="header-anchor" href="#chat-model" aria-label="Permalink to &quot;Chat model&quot;">​</a></h2><p>Open <strong>Settings → Chat model</strong> and choose a preset or a custom service:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Protocol</th><th>Default Base URL</th></tr></thead><tbody><tr><td>DeepSeek</td><td>OpenAI Chat</td><td><code>https://api.deepseek.com/v1</code></td></tr><tr><td>Alibaba Cloud Bailian</td><td>OpenAI Chat</td><td><code>https://dashscope.aliyuncs.com/compatible-mode/v1</code></td></tr><tr><td>Zhipu GLM</td><td>OpenAI Chat</td><td><code>https://open.bigmodel.cn/api/paas/v4</code></td></tr><tr><td>Moonshot Kimi</td><td>OpenAI Chat</td><td><code>https://api.moonshot.cn/v1</code></td></tr><tr><td>Volcengine Ark</td><td>OpenAI Chat</td><td><code>https://ark.cn-beijing.volces.com/api/v3</code></td></tr><tr><td>OpenAI</td><td>OpenAI Chat</td><td><code>https://api.openai.com/v1</code></td></tr><tr><td>Anthropic</td><td>Anthropic Messages</td><td><code>https://api.anthropic.com/v1</code></td></tr><tr><td>Google Gemini</td><td>Gemini</td><td><code>https://generativelanguage.googleapis.com/v1beta</code></td></tr><tr><td>Custom</td><td>Any of the four protocols</td><td>Supplied by you</td></tr></tbody></table><p><code>@hearth/model-client</code> normalizes all four protocols into one streaming agent turn: text deltas, tool calls, argument assembly, finish reason, and usage. Changing providers does not change the runtime loop.</p><h3 id="how-the-key-is-stored" tabindex="-1">How the key is stored <a class="header-anchor" href="#how-the-key-is-stored" aria-label="Permalink to &quot;How the key is stored&quot;">​</a></h3><p>The key is written to <code>.hearth/model-settings.json</code>, with permissions set to <code>0600</code> where the platform supports it. The settings API returns only a masked value such as <code>sk-1••••abcd</code>, never the raw key.</p><h3 id="the-model-must-support-tool-calling" tabindex="-1">The model must support tool calling <a class="header-anchor" href="#the-model-must-support-tool-calling" aria-label="Permalink to &quot;The model must support tool calling&quot;">​</a></h3><p>The native executor depends on structured tool calls. If the selected model does not support them, Hearth returns an explicit error instead of treating a plain text answer as a completed task.</p><h2 id="codex-executor" tabindex="-1">Codex executor <a class="header-anchor" href="#codex-executor" aria-label="Permalink to &quot;Codex executor&quot;">​</a></h2><p>The Codex executor reads your existing <code>~/.codex/config.toml</code> and does not require <code>codex login</code>. If a <code>model_provider</code> and its <code>env_key</code> are configured, the key only needs to exist in the terminal that starts Hearth.</p><p>Settings shows:</p><ul><li>Provider and model.</li><li>Base URL and wire API.</li><li>Environment-variable name and whether it was read.</li><li>Config path and current issues.</li></ul><p>After changing <code>config.toml</code> or the environment, click <strong>Re-detect</strong>. No server restart is required.</p><h3 id="how-the-two-executors-are-chosen" tabindex="-1">How the two executors are chosen <a class="header-anchor" href="#how-the-two-executors-are-chosen" aria-label="Permalink to &quot;How the two executors are chosen&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Executor</th><th>Suitable work</th><th>Default behavior</th></tr></thead><tbody><tr><td><code>native</code></td><td>General analysis, writing, summarization, simple file work</td><td>General tasks use the native runtime</td></tr><tr><td><code>codex</code></td><td>Repositories, multi-file edits, tests, commits</td><td>Explicit engineering work uses Codex</td></tr></tbody></table><p>Failures never silently switch executors. The run manifest records the actual executor so the result can be audited.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Still unconfigured after saving?</strong> Check that Base URL, model, and API key are all non-empty, then click <strong>Test connection</strong>.</p><p><strong>Codex shows disconnected?</strong> Check that the <code>env_key</code> variable exists in the terminal that starts Hearth. On Windows, reopen the terminal or restart the service after changing user environment variables.</p><p><strong>Can I use two chat providers at once?</strong> The settings store one chat-model configuration. Different tasks can use different executors, but the chat model is global.</p>',22)])])}const m=t(r,[["render",n]]);export{p as __pageData,m as default};
